def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Prioritize stacks that are expected to be retrieval-ready based on current and future needs
    if AVG == 0:
        predictive_readiness = 1.0
    else:
        if CUR == 0:
            predictive_readiness = 0.0
        else:
            predictive_readiness = (AVG - CUR) / (CUR + 1) if AVG > CUR else 0.0

    # Encourage stacks that are coherent with the current container
    if AVG == 0:
        coherence_bonus = 1.0
    else:
        if CUR == 0:
            coherence_bonus = 0.0
        else:
            coherence_bonus = (AVG - CUR) / (AVG + 1) if AVG > CUR else 0.0

    # Blockage factor: fewer containers with smaller IDs mean less blocking
    blockage_factor = (RI + 1)

    # Encourage free space: stacks with more available slots are better
    space_factor = 1 / (EMP + 1)

    # Stacks with lower average IDs are more retrieval-ready if they are known
    if CUR == 0:
        stability_factor = 0.0
    else:
        stability_factor = AVG / (CUR + 1)

    # Urgency: prioritize stacks where current container can be placed without blocking
    if AVG == 0:
        urgency_factor = 1.0
    else:
        urgency_factor = (CUR / AVG) * (RI + 1)

    # Readiness: smaller stacks with lower average IDs have better potential
    readiness = (1 / (SH + 1)) * (1 / (AVG + 1)) if AVG != 0 else 0.0

    # Future blockage estimation based on unknowns
    if CUR == 0:
        future_blockage = 0.0
    else:
        if AVG == 0:
            future_blockage = 1.0
        else:
            future_blockage = max(0, (CUR - AVG) / (CUR + 1)) * 0.5

    # Adaptive coherence: stacks with average close to current container are more future-ready
    if CUR == 0:
        adaptive_coherence = 0.0
    elif AVG == 0:
        adaptive_coherence = 1.0
    else:
        adaptive_coherence = max(0, (AVG - CUR) / (AVG + 1)) * 0.6

    # Combine all contributions with systematic weights, introducing a small deterministic differentiator
    priority = (
        (blockage_factor * space_factor) +
        (stability_factor * 0.2) +
        (urgency_factor * 0.25) +
        (EMP * 0.05) +
        (coherence_bonus * 0.15) +
        (readiness * 0.1) +
        (future_blockage * 0.15) +
        (predictive_readiness * 0.1) +
        (adaptive_coherence * 0.1) +
        (AVG * 0.001)  # Introduce a small deterministic differentiator
    )
    return priority

def priority(SH, EMP, AVG, CUR, RI, DIFF):
    # Flexibility and stack preference metrics
    flexibility = (100 - SH) * 0.1 + EMP * 0.05
    if EMP > 50:
        flexibility += (EMP - 50) * 0.1
    if SH < 20:
        flexibility += (20 - SH) * 0.2
    flexibility += 1 / (SH + 1) * 5
    if SH > 50:
        flexibility -= SH * 0.05
    if abs(AVG - CUR) < 10:
        flexibility += (10 - abs(AVG - CUR)) * 0.1

    # Alignment bonus based on AVG and CUR
    alignment_bonus = 0
    if AVG < CUR - 10:
        alignment_bonus = (CUR - AVG) * 0.1
    elif AVG < CUR:
        alignment_bonus = (CUR - AVG) * 0.05
    elif AVG > CUR:
        alignment_bonus = -(AVG - CUR) * 0.05

    if DIFF > 0:
        # Safe stack: combine metrics for flexibility, alignment, and stack characteristics
        priority = (AVG - CUR) * 0.1 + (100 - EMP) * 0.05 + SH * 0.07 + (np.log(DIFF + 1)) * 0.5 + alignment_bonus
        # Additional flexibility and alignment rewards
        priority += flexibility * 0.2
        if AVG > CUR:
            priority += (AVG - CUR) * 0.05
        if SH < 20:
            priority += (20 - SH) * 0.1
        if SH > 50:
            priority -= SH * 0.03
        if EMP < 10:
            priority -= (100 - EMP) * 0.2
    else:
        # Unsafe stack: apply penalties with refined flexibility and alignment considerations
        penalty = 1e6 + RI * 20 + (100 - EMP) * 10 + SH * 5 + (AVG - CUR) * 1.2
        # Additional penalties for near-full stacks and low-average stacks
        if EMP < 10:
            penalty += (100 - EMP) * 30
        if AVG < CUR:
            penalty += (CUR - AVG) * 15
        if SH > 50:
            penalty += SH * 3
        if EMP > 80:
            penalty += (100 - EMP) * 10
        if AVG > CUR:
            penalty -= (AVG - CUR) * 5
        # Refine penalty based on average ID with a smooth, non-linear adjustment
        if AVG > CUR:
            penalty -= (AVG - CUR) * 2.5 * (1 / (1 + np.exp(-0.02 * (AVG - CUR))))
        # Reduce penalty based on flexibility and alignment bonus
        penalty -= flexibility * 0.5
        penalty -= alignment_bonus
        # Strengthen penalty based on RI and flexibility
        penalty += RI * (100 - SH) * 0.02
        penalty -= flexibility * 0.1
        priority = penalty
    return priority

import math

def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Reward empty stacks heavily
    if DIFF == 1e9:
        return 0  # Empty stack is best (lowest score)

    # Min-Max: prefer safe stacks (DIFF > 0) with smallest DIFF, else stacks with largest DIFF
    minmax_score = (DIFF if DIFF > 0 else 1e10 - DIFF) * 100

    # Penalize based on available space (more severe penalty for less space)
    space_penalty = (1000 / (EMP + 1)) if EMP > 0 else float('inf')

    # Penalize stacks with more blocked containers (RI)
    block_penalty = RI ** 1.5 * 10  # Stronger penalty for higher RI

    # Context-aware RI penalty: penalize more when AVG > CUR, but scale back for very tall stacks
    ri_penalty = RI ** 1.5 * 10 * (1 + (AVG - CUR) * 0.2) * (1 - (SH - 10) / 100)

    # Enhanced alignment penalty: more severe on unsafe stacks (DIFF < 0)
    avg_penalty = (AVG - CUR) * 2 * (1 + 0.5 * (DIFF < 0))

    # Additional penalty for stacks where AVG > CUR on unsafe stacks (increasing future blocking)
    if DIFF < 0 and AVG > CUR:
        avg_penalty += (AVG - CUR) * 1.5

    # Strong penalty for stacks where AVG is much higher than CUR on unsafe stacks
    if DIFF < 0 and (AVG - CUR) > 10:
        avg_penalty += (AVG - CUR) * 10

    # Custom penalty based on AVG > CUR on unsafe stacks, scaled by adaptive exponential function
    if DIFF < 0:
        avg_penalty += (AVG - CUR) * max(1, math.exp((AVG - CUR) / 20)) * 2

    # Penalize tall stacks with little room for future moves
    height_penalty = ((SH - 10) / 10) ** 3 * 50  # Stronger emphasis on height

    # Dynamic height-based penalty that considers stack height and potential future blocking
    height_flexibility_penalty = ((SH - 10) / 10) ** 2 * (1 + (AVG - CUR) * 0.05) * 30 if DIFF < 0 else 0

    # Bonus for stacks with high EMP and low SH (more flexibility)
    flexibility_bonus = (EMP / (SH + 1)) * 100

    # Additional flexibility bonus for unsafe stacks
    if DIFF < 0:
        flexibility_bonus += (EMP / (SH + 1)) * 200

    # Bonus for stacks with lower AVG in unsafe states, to reduce future blocking
    if DIFF < 0:
        avg_bonus = (CUR - AVG) * 1.5
    else:
        avg_bonus = 0

    # Bonus for stacks with high flexibility and low AVG on unsafe stacks
    if DIFF < 0:
        flexibility_avg_bonus = (EMP / (SH + 1)) * 50 + (CUR - AVG) * 1.2
    else:
        flexibility_avg_bonus = 0

    # Strong penalty for stacks that block a lot of lower-ID containers (RI is high)
    ri_penalty = RI ** 1.5 * 10

    # Stronger penalty for unsafe stacks with very low flexibility (EMP < 2)
    if DIFF < 0 and EMP < 2:
        flexibility_penalty = (10 - EMP) * 1000
    else:
        flexibility_penalty = 0

    # Bonus for safe stacks with high flexibility and low AVG
    if DIFF > 0:
        safe_bonus = (EMP / (SH + 1)) * 150 + (CUR - AVG) * 1.0
    else:
        safe_bonus = 0

    # Additional bonus for safe stacks with high flexibility and very low AVG
    if DIFF > 0:
        safe_bonus += (EMP / (SH + 1)) * 200 * (1 / (1 + math.exp((AVG - CUR) / 10)))

    # New: bonus for safe stacks where many future containers can be placed above CUR without creating blocking
    if DIFF > 0:
        future_placement_bonus = (EMP / (SH + 1)) * (1 + (1 / (1 + math.exp((AVG - CUR) / 15)))) * 150
    else:
        future_placement_bonus = 0

    # Stronger emphasis on low AVG in unsafe stacks (penalty for high AVG in unsafe stacks)
    if DIFF < 0:
        avg_penalty += (AVG - CUR) * max(1, math.exp((AVG - CUR) / 15)) * 5

    # Bonus for stacks in unsafe states where AVG < CUR, to reduce likelihood of future blocking
    if DIFF < 0 and AVG < CUR:
        avg_bonus += (CUR - AVG) * math.exp((CUR - AVG) / 20) * 2

    # Bonus for stacks in unsafe states where AVG is close to CUR (reduces potential for future blocking)
    if DIFF < 0:
        avg_bonus += (1 / (1 + math.exp((AVG - CUR) / 10))) * 100

    # Bonus for stacks in unsafe states where AVG is close to CUR
    if DIFF < 0:
        directional_bonus = (1 / (1 + math.exp((AVG - CUR) / 10))) * 50
    else:
        directional_bonus = 0

    # New: stronger alignment bonus for safe stacks with AVG close to CUR
    if DIFF > 0:
        alignment_bonus = (1 / (1 + math.exp((AVG - CUR) / 20))) * 200
    else:
        alignment_bonus = 0

    # New: additional strong alignment bonus for safe stacks with very close AVG to CUR
    if DIFF > 0:
        very_close_bonus = (1 / (1 + math.exp((AVG - CUR) / 10))) * 300
    else:
        very_close_bonus = 0

    # Penalty for future blocking based on AVG and CUR in unsafe stacks
    future_block_penalty = 0
    if DIFF < 0:
        avg_diff = AVG - CUR
        if avg_diff > 0:
            future_block_penalty = avg_diff * SH * 0.1  # Higher AVG leads to more potential future blocking

    # New: additional focused penalty for dangerous stacks that are tall, nearly full, and have high RI
    if DIFF < 0:
        dangerous_stack_penalty = ((SH - 10) ** 2) * (10 - EMP) * (RI + 1) * (0.3 + 0.2 * (SH - 10) / 50)
    else:
        dangerous_stack_penalty = 0

    # New: penalty for increased future blocking by placing CUR in a stack with many higher-ID containers
    future_blocking_penalty = 0
    if DIFF < 0:
        avg_diff = AVG - CUR
        if avg_diff > 0:
            future_blocking_penalty = avg_diff * (RI + 1) * 0.2  # More blocked containers = higher penalty

    # Dynamic weight adjustment based on stack safety
    weight_factor = 1.0
    if DIFF > 0:
        weight_factor = 0.8  # reduce penalty for safe stacks
    elif DIFF < 0:
        weight_factor = 2.0  # increase penalty for unsafe stacks

    # Final priority score with dynamic weight adjustment
    priority = (minmax_score + space_penalty + block_penalty + avg_penalty + height_penalty + ri_penalty + height_flexibility_penalty 
                - flexibility_bonus - avg_bonus - flexibility_avg_bonus + flexibility_penalty + safe_bonus + directional_bonus 
                + alignment_bonus + very_close_bonus + future_block_penalty + future_placement_bonus + dangerous_stack_penalty + future_blocking_penalty) * weight_factor
    return priority

def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Curvature-aware phase-sensitive DIFF decay with logarithmic underfill amplification
    if DIFF <= 1e4:
        weight_diff = 0.01 * (DIFF / 1e4) * (1 + (SH / 1000)) ** 0.6 * (1 + (EMP / 10)) ** 0.4 * (1 + (SH / 1000)) ** 0.15
    elif DIFF <= 1e5:
        weight_diff = 0.02 + 0.01 * (DIFF / 1e5) * (1 + (SH / 1000)) ** 0.6 * (1 + (EMP / 10)) ** 0.4 * (1 + (SH / 1000)) ** 0.15
    else:
        weight_diff = 0.05 * (DIFF / 1e9) ** 0.7 * (1 + (SH / 1000)) ** 0.6 * (1 + (EMP / 10)) ** 0.4 * (1 + (SH / 1000)) ** 0.15

    # Exponential RI normalization with height-adaptive curvature
    if RI > 30:
        weight_ri = 1.3 / (1 + (RI / 30)) ** 1.5 * (1 + (SH / 1000)) ** 0.6 * (1 + (SH / 1000)) ** 0.3
    elif RI > 20:
        weight_ri = 1.7 / (1 + (RI / 25)) ** 1.5 * (1 + (SH / 1000)) ** 0.6 * (1 + (SH / 1000)) ** 0.3
    else:
        weight_ri = 2.2 / (1 + (RI / 15)) ** 1.5 * (1 + (SH / 1000)) ** 0.6 * (1 + (SH / 1000)) ** 0.3

    # Age-biased AVG alignment with utilization-aware curvature modulation
    avg_diff = AVG - CUR
    if avg_diff > 30:
        weight_avg = 0.25 / (1 + (avg_diff ** 0.75)) * (1 + (SH / 1000)) ** 0.45 * (1 + (EMP / 10)) ** 0.6 * (1 / (1 + SH * 0.03))
    elif avg_diff > 15:
        weight_avg = 0.2 + 0.05 * (avg_diff / 30) * (1 + (SH / 1000)) ** 0.45 * (1 + (EMP / 10)) ** 0.6 * (1 / (1 + SH * 0.03))
    elif avg_diff > 5:
        weight_avg = 0.15 + 0.05 * (avg_diff / 20) * (1 + (SH / 1000)) ** 0.45 * (1 + (EMP / 10)) ** 0.6 * (1 / (1 + SH * 0.03))
    else:
        weight_avg = 0.1 * (1 + (SH / 1000)) ** 0.45 * (1 + (EMP / 10)) ** 0.6 * (1 / (1 + SH * 0.03))

    # Utilization-aware prioritization with curvature-adaptive underfill mitigation and exponential stack age bias
    utilization = EMP / SH if SH > 0 else 1.0
    curvature_factor = (1 + (SH / 1000)) ** 0.3
    age_factor = 1.0 / (1 + SH * 0.03)
    if utilization < 0.2:
        weight_emp = 0.07 * (1 + (SH / 1000)) ** 0.5 * (1 / (1 + (EMP / 10))) * age_factor * curvature_factor
    elif utilization < 0.4:
        weight_emp = 0.035 * (1 + (SH / 1000)) ** 0.5 * (1 / (1 + (EMP / 10))) * age_factor * curvature_factor
    else:
        weight_emp = 0.015 * (1 + (SH / 1000)) ** 0.5 * (1 / (1 + (EMP / 10))) * age_factor * curvature_factor

    # Curvature-adaptive balancing of components to reduce overfitting in phase boundaries
    curvature_balance = (1 + (SH / 1000)) ** 0.2 * (1 + (EMP / 10)) ** 0.1 * (1 + (RI / 10)) ** 0.1

    # Final priority calculation
    priority = (RI * weight_ri + avg_diff * weight_avg - utilization * weight_emp + (DIFF / 1e9) * weight_diff) * curvature_balance
    return priority

def priority_v2(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Min-Max: the closest safe stack (DIFF > 0) first, else the stack with the largest DIFF;
    # ties go to the lowest stack, but prioritize stacks with more free space (EMP) more strongly
    priority = (DIFF if DIFF > 0 else 1e10 - DIFF) * 100 + AVG * 40 - EMP * 30
    return priority

def priority_v2(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Emphasize stacks that are safe (DIFF > 0), provide room (EMP), and reduce blocking potential (RI)
    if DIFF > 0:
        # Safe stacks: prioritize stability, EMP, and minimize RI
        priority = (DIFF * 1.5) + (RI * 0.3) + (1000 - EMP) * 0.1 + (AVG * 0.05) + (SH * 0.02)
    else:
        # Unsafe stacks: prioritize EMP heavily, penalize RI, and consider other factors
        priority = (1e10 - DIFF) * 0.4 + (RI * 1.2) + (1000 - EMP) * 0.3 + (AVG * 0.2) + (SH * 0.03)
    return priority

def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    if DIFF > 0:
        # Safe stack: prioritize more empty space, lower average ID, and penalize height slightly
        priority = (DIFF * 100) + (20 * EMP) - (5 * AVG) + (SH * 0.05)
    else:
        # Unsafe stack: strong penalty for height, blocked containers, low space, and high average ID
        priority = (1e10 - DIFF) * 100 + (SH * 15) + (RI * 70) + (AVG - CUR) * 10 - (EMP * 15) + (AVG - CUR) * 25
    return priority

def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    if DIFF > 0:
        return (DIFF * 100) + (RI * 15) + (AVG - CUR) * 0.1 + SH * 0.01 + (EMP ** 2) * 0.5 + (EMP / (SH + 1)) * 10 + (1 / (EMP + 1)) * 50 + (SH / (SH + EMP + 1)) * 15 + (EMP / (SH + 1)) * 2.5
    else:
        return (1e10 - DIFF) * 100 + (RI * 450) + (RI ** 2) * 10 + (CUR - AVG) * 0.5 + (1 / (EMP + 1)) * 600 - EMP * 5 + SH * 1 + (EMP ** 2) * 0.3 + (1 / (EMP + 1)) * 200 + (SH / (SH + EMP + 1)) * 100 + (1 / (SH + 1)) * 75

def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    base_priority = (DIFF if DIFF > 0 else 1e10 - DIFF) * 100
    priority = base_priority + AVG * 10 + (100 - EMP) * 5 + SH * 10 + RI * 20

    if DIFF <= 0:
        priority += (100 - EMP) * 20
    else:
        priority -= (100 - EMP) * 10

    if DIFF <= 0:
        priority += (SH / (EMP + 1)) * 50
    else:
        priority -= (SH / (EMP + 1)) * 10

    priority += (RI / (EMP + 1)) * 100

    if AVG < CUR:
        priority += AVG * (1 + (1 / (SH + 1)))

    if (SH + 1) / (EMP + 1) > 3 and AVG > CUR:
        priority += (SH / (EMP + 1)) * 20

    if EMP > 0:
        priority += (RI / EMP) * 30

    avg_diff = abs(AVG - CUR)
    if avg_diff < 20:
        priority += (20 - avg_diff) * 50

    if DIFF <= 0 and (SH + 1) / (EMP + 1) > 3:
        priority += (100 - EMP) * 30

    priority += (RI + 1) * (100 / (SH + 1)) * (1 + (100 - EMP) / 100)

    if DIFF > 0 and EMP < 20:
        priority -= (20 - EMP) * 5

    if AVG > CUR:
        priority += (AVG - CUR) * 10 * (1 + (SH / 100))

    return priority

def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    density = SH / EMP if EMP > 0 else 0
    if DIFF > 0:
        # Safe stacks: prioritize based on AVG, RI, and EMP
        priority = DIFF * 10 + RI * 5 + SH / 10 - EMP * 2 + AVG * 0.5 + (AVG - CUR) * (EMP / 10)
    else:
        # Unsafe stacks: penalize based on DIFF, but adjust based on EMP and AVG
        priority = (1e10 - DIFF) * 10 + RI * 10 + SH / 10 - EMP * 2 + AVG * 0.5 + SH * 1.5 + (AVG - CUR) * (EMP / 10) - EMP * 0.5 + (AVG - CUR) * 0.2 + density * 10 - abs(AVG - CUR) * 2
    return priority
